mapper.update:
UPDATE auth_session AS session
JOIN system_user AS u
  ON u.tenant_id = session.tenant_id
 AND u.id = session.user_id
SET session.last_active_time = #{now}, session.version = session.version + 1
WHERE session.session_id = #{sessionId}
  AND session.tenant_id = #{tenantId}
  AND session.user_id = #{userId}
  AND session.user_version = #{userVersion}
  AND u.auth_epoch = #{userVersion}
  AND u.status = 1
  AND u.deleted = 0
  AND session.status = 'ACTIVE'
  AND session.expires_at > #{now}

UPDATE auth_session
SET status = 'REVOKED',
    revoked_at = #{now},
    revocation_reason = #{reason},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND session_id = #{sessionId}
  AND status = 'ACTIVE'
  AND expires_at > #{now}

mapper.select:
SELECT tenant_id, principal_key, user_id, failure_count, window_started_at,
       locked_until, last_failure_at, version
FROM auth_login_security_state
WHERE tenant_id = #{tenantId}
  AND principal_key = #{principalKey}
LIMIT 1

mapper.delete:
DELETE FROM auth_login_security_state
WHERE tenant_id = #{tenantId}
  AND principal_key = #{principalKey}

DELETE FROM auth_login_security_state
WHERE (locked_until IS NULL OR locked_until <= #{now})
  AND last_failure_at < #{staleBefore}
ORDER BY last_failure_at, tenant_id, principal_key
LIMIT #{batchSize}

DELETE FROM auth_session
WHERE expires_at < #{staleBefore}
   OR (status = 'REVOKED' AND revoked_at < #{staleBefore})
ORDER BY expires_at, session_id
LIMIT #{batchSize}
